tool_input.command:
mkdir -p scratch && cat > scratch/analyze.mjs <<'EOF'
import fs from 'fs';
const d = JSON.parse(fs.readFileSync('inputs/points.json','utf8'));
const xyz = d.xyz, rgb = d.rgb;
// Filter to plausible room bounds
const pts = xyz.map((p,i)=>({p,c:rgb[i]})).filter(({p})=>p[0]>-1.6&&p[0]<1.6&&p[1]>-0.2&&p[1]<2.2&&p[2]>-2.6&&p[2]<4.2);
console.log('in-room points:', pts.length);
// XZ density map at 0.2m cells, printed as ASCII with dominant height band
const x0=-1.6,z0=-2.6,cs=0.2, W=16, H=34;
const grid = Array.from({length:H},()=>Array.from({length:W},()=>({n:0,maxy:-9,sumc:[0,0,0]})));
for (const {p,c} of pts){
  const ix=Math.floor((p[0]-x0)/cs), iz=Math.floor((p[2]-z0)/cs);
  if(ix<0||ix>=W||iz<0||iz>=H) continue;
  const g=grid[iz][ix]; g.n++; g.maxy=Math.max(g.maxy,p[1]);
  g.sumc[0]+=c[0];g.sumc[1]+=c[1];g.sumc[2]+=c[2];
}
console.log('XZ map (rows z from '+z0+' increasing, cols x from '+x0+'): char = density, digit after = maxY');
for(let iz=0;iz<H;iz++){
  let row='';
  for(let ix=0;ix<W;ix++){
    const g=grid[iz][ix];
    if(g.n===0) row+=' .'; 
    else if(g.n<4) row+=' ,';
    else {
      const m=g.maxy;
      row+= m<0.15?' _': m<0.5?' l': m<1.0?' m': m<1.6?' h':' H';
    }
  }
  console.log((z0+iz*cs).toFixed(1).padStart(5)+' '+row);
}
console.log('    '+Array.from({length:W},(_,i)=>((x0+i*cs).toFixed(1)+' ').slice(0,2)).join(''));
EOF
node scratch/analyze.mjs
